#!/usr/bin/env Rscript

# Recalibrate the frozen-Bdev trajectory-membership gate with sample-aware
# weights. This is report-only and reuses the held-out Bdev scores generated by
# analysis 81; PeakVI and all source bundles remain unchanged.

options(stringsAsFactors = FALSE, warn = 1, width = 180)
args <- commandArgs(trailingOnly = TRUE)
if (length(args) != 6L) stop(paste(
  "Usage: 82_bdev_sample_weighted_trajectory_gate.R BASE_REPORT",
  "QUERY_PROJECTION SIGNAL_SCORES ORIGINAL_REGIONS OUTPUT_DIR VERSION"
), call. = FALSE)

base_dir <- normalizePath(args[[1L]], mustWork = TRUE)
projection_path <- normalizePath(args[[2L]], mustWork = TRUE)
signal_path <- normalizePath(args[[3L]], mustWork = TRUE)
region_path <- normalizePath(args[[4L]], mustWork = TRUE)
output_dir <- normalizePath(args[[5L]], mustWork = FALSE)
script_version <- args[[6L]]
if (file.exists(output_dir) || dir.exists(output_dir))
  stop("Output already exists: ", output_dir, call. = FALSE)
stage_dir <- paste0(output_dir, ".incomplete")
if (file.exists(stage_dir) || dir.exists(stage_dir))
  stop("Incomplete output already exists: ", stage_dir, call. = FALSE)
dir.create(file.path(stage_dir, "figures"), recursive = TRUE,
  showWarnings = FALSE)

suppressPackageStartupMessages({
  library(data.table)
  library(ggplot2)
  library(patchwork)
  library(jsonlite)
})

write_tsv <- function(x, path) fwrite(x, path, sep = "\t", na = "NA")
weighted_rate <- function(hit, weight) sum(weight * hit) / sum(weight)
make_roc <- function(d, weight) {
  ord <- order(d$trajectory_support, decreasing = TRUE)
  z <- d[ord]
  w <- weight[ord]
  on_total <- sum(w[z$trajectory_truth])
  off_total <- sum(w[!z$trajectory_truth])
  roc <- data.table(
    threshold = c(Inf, z$trajectory_support),
    sensitivity = c(0, cumsum(w * z$trajectory_truth) / on_total),
    specificity = c(1, 1 - cumsum(w * !z$trajectory_truth) / off_total))
  roc[, youden_j := sensitivity + specificity - 1]
  roc[, false_positive_rate := 1 - specificity]
  roc
}
fit_cutoff <- function(d, weight) {
  roc <- make_roc(d, weight)
  roc$threshold[[which.max(roc$youden_j)]]
}

cv_path <- file.path(base_dir,
  "bdev_leave_one_sample_out_trajectory_support.tsv.gz")
query_path <- file.path(base_dir,
  "query_trajectory_support_and_acceptance.tsv.gz")
cv <- fread(cmd = paste("zcat", shQuote(cv_path)))
query <- fread(cmd = paste("zcat", shQuote(query_path)))
base_density <- fread(file.path(base_dir,
  "query_bdev_normalized_density_by_policy.tsv"))
stopifnot(nrow(cv) == 26723L, sum(cv$trajectory_truth) == 12642L,
  nrow(query) == 23252L, all(c("current_accepted", "mapped_pt",
    "trajectory_support") %in% names(query)))

# Equal-sample/class weights make every sample contribute the same total weight
# within each truth class. Reliability weights retain that class balance but
# let samples contribute in proportion to sqrt(number of on-trajectory cells).
sample_counts <- cv[, .(n_cells = .N,
  n_on_trajectory = sum(trajectory_truth),
  n_off_trajectory = sum(!trajectory_truth)), by = held_out_sample]
cv <- sample_counts[cv, on = "held_out_sample"]
cv[, pooled_weight := 1]
cv[, equal_sample_weight := fifelse(trajectory_truth,
  1 / n_on_trajectory, 1 / n_off_trajectory)]
cv[, reliability := sqrt(n_on_trajectory)]
cv[, sqrt_on_weight := fifelse(trajectory_truth,
  reliability / n_on_trajectory, reliability / n_off_trajectory)]

policy_info <- data.table(
  policy = c("Pooled-cell cutoff", "Equal-sample cutoff",
    "Sqrt-on reliability cutoff"),
  weight_column = c("pooled_weight", "equal_sample_weight",
    "sqrt_on_weight"),
  role = c("Existing Bdev balanced approach", "Sensitivity analysis",
    "Primary new approach"))
policy_info[, cutoff := vapply(weight_column, function(col)
  fit_cutoff(cv, cv[[col]]), numeric(1))]

cutoff_summary <- rbindlist(lapply(seq_len(nrow(policy_info)), function(i) {
  p <- policy_info[i]
  w <- cv[[p$weight_column]]
  pred <- cv$trajectory_support >= p$cutoff
  per_sample <- cv[, .(
    sensitivity = mean(trajectory_support[trajectory_truth] >= p$cutoff),
    specificity = mean(trajectory_support[!trajectory_truth] < p$cutoff)),
    by = held_out_sample]
  data.table(policy = p$policy, role = p$role, cutoff = p$cutoff,
    calibration_weighted_sensitivity = weighted_rate(
      pred[cv$trajectory_truth], w[cv$trajectory_truth]),
    calibration_weighted_specificity = weighted_rate(
      !pred[!cv$trajectory_truth], w[!cv$trajectory_truth]),
    pooled_sensitivity = mean(pred[cv$trajectory_truth]),
    pooled_specificity = mean(!pred[!cv$trajectory_truth]),
    minimum_sample_balanced_accuracy = min(rowMeans(
      per_sample[, .(sensitivity, specificity)])),
    maximum_sample_balanced_accuracy = max(rowMeans(
      per_sample[, .(sensitivity, specificity)])))
}))

sample_performance <- rbindlist(lapply(seq_len(nrow(policy_info)), function(i) {
  p <- policy_info[i]
  cv[, .(n_cells = .N, n_on_trajectory = sum(trajectory_truth),
    n_off_trajectory = sum(!trajectory_truth),
    sensitivity = mean(trajectory_support[trajectory_truth] >= p$cutoff),
    specificity = mean(trajectory_support[!trajectory_truth] < p$cutoff)),
    by = held_out_sample][, `:=`(policy = p$policy,
      balanced_accuracy = (sensitivity + specificity) / 2)]
}))

for (i in seq_len(nrow(policy_info))) {
  nm <- paste0("accept_", i)
  set(query, j = nm, value = query$current_accepted &
    query$trajectory_support >= policy_info$cutoff[[i]])
}
policy_query <- rbindlist(lapply(seq_len(nrow(policy_info)), function(i) {
  ans <- copy(query)
  ans[, `:=`(policy = policy_info$policy[[i]],
    accepted = get(paste0("accept_", i)))]
  ans
}))
policy_query[, policy := factor(policy, levels = policy_info$policy)]

acceptance <- policy_query[, .(
  n_query_cells = .N,
  n_currently_mapped = sum(current_accepted),
  n_accepted = sum(accepted),
  accepted_fraction_currently_mapped = sum(accepted) /
    sum(current_accepted)),
  by = .(policy, sample_id, knockout_target, genotype)]

# Reuse the unchanged 100-bin Bdev density grid from analysis 81. Filtered
# query fractions keep the current-mapped sample total as a fixed denominator.
bdev_grid <- unique(base_density[, .(bin, bin_left, bin_right, bin_midpoint,
  bdev_n_cells, bdev_fraction, bdev_rolling_fraction)])
setorder(bdev_grid, bin)
stopifnot(nrow(bdev_grid) == 100L)
breaks <- c(bdev_grid$bin_left[[1L]], bdev_grid$bin_right)
assign_bin <- function(pt) pmin(100L, pmax(1L,
  findInterval(pt, breaks, all.inside = TRUE)))
current_totals <- query[current_accepted & is.finite(mapped_pt),
  .(fixed_denominator = .N), by = .(knockout_target, genotype)]
density <- rbindlist(lapply(policy_info$policy, function(policy_i) {
  rbindlist(lapply(c("Flt3l", "Il7"), function(target_i) {
    rbindlist(lapply(c("WT", "KO"), function(genotype_i) {
      cells <- policy_query[policy == policy_i & knockout_target == target_i &
        genotype == genotype_i & accepted & is.finite(mapped_pt)]
      counts <- cells[, .(n_cells = .N), by = .(bin = assign_bin(mapped_pt))]
      ans <- merge(copy(bdev_grid), counts, by = "bin", all.x = TRUE)
      ans[is.na(n_cells), n_cells := 0L]
      den <- current_totals[knockout_target == target_i &
        genotype == genotype_i, fixed_denominator]
      ans[, `:=`(policy = policy_i, target = target_i,
        genotype = genotype_i, total_accepted = nrow(cells),
        fixed_denominator = den,
        fixed_denominator_cell_fraction = n_cells / den)]
      ans[, fixed_denominator_rolling_fraction := frollmean(
        fixed_denominator_cell_fraction, 3L, align = "center",
        fill = NA_real_)]
      ans[, bdev_normalized_rolling_fraction :=
        fixed_denominator_rolling_fraction / bdev_rolling_fraction]
      ans[!is.finite(bdev_normalized_rolling_fraction),
        bdev_normalized_rolling_fraction := NA_real_]
      ans
    }))
  }))
}))
density[, policy := factor(policy, levels = policy_info$policy)]

wt_above <- density[genotype == "WT" &
  is.finite(bdev_normalized_rolling_fraction) &
  bdev_normalized_rolling_fraction > 1]
setorder(wt_above, policy, target, bin)
wt_above[, run := cumsum(seq_len(.N) == 1L |
  policy != shift(policy, fill = policy[[1L]]) |
  target != shift(target, fill = target[[1L]]) |
  bin != shift(bin, fill = bin[[1L]] - 1L) + 1L)]
enrichment_regions <- wt_above[, .(first_bin = min(bin),
  last_bin = max(bin), n_bins = .N, pt_left = min(bin_left),
  pt_right = max(bin_right),
  maximum_wt_ratio = max(bdev_normalized_rolling_fraction)),
  by = .(policy, target, run)]
setorder(enrichment_regions, policy, target, pt_left)
enrichment_regions[, peak_number := seq_len(.N), by = .(policy, target)]
enrichment_regions[, region_id := paste0(target, "_peak", peak_number)]

original_regions <- fread(region_path)[target %in% c("Flt3l", "Il7")]
region_retention <- rbindlist(lapply(seq_len(nrow(original_regions)), function(i) {
  reg <- original_regions[i]
  policy_query[knockout_target == reg$target & is.finite(mapped_pt) &
    mapped_pt >= reg$pt_left & mapped_pt < reg$pt_right,
    .(n_original_region_cells = .N, n_accepted = sum(accepted),
      accepted_fraction = mean(accepted)), by = .(policy, genotype)][,
      `:=`(region_id = reg$region_id, target = reg$target,
        pt_left = reg$pt_left, pt_right = reg$pt_right)]
}))

signal <- fread(cmd = paste("zcat", shQuote(signal_path)))[
  panel_label %in% c("Flt3L UP", "IL-7 UP")]
signal[, expected_target := fifelse(panel_label == "Flt3L UP", "Flt3l", "Il7")]
signal <- signal[knockout_target == expected_target,
  .(source_cell_id = cell_id, panel_label, aggregate_score)]
signal_policy <- merge(policy_query[accepted & is.finite(mapped_pt)], signal,
  by = "source_cell_id")
signal_bins <- signal_policy[, .(n_cells = .N,
  score_sum = sum(aggregate_score)), by = .(policy, knockout_target,
    genotype, bin = assign_bin(mapped_pt), panel_label)]
signal_trajectory <- merge(CJ(policy = factor(policy_info$policy,
  levels = policy_info$policy), knockout_target = c("Flt3l", "Il7"),
  genotype = c("WT", "KO"), bin = seq_len(100L), unique = TRUE),
  signal_bins, by = c("policy", "knockout_target", "genotype", "bin"),
  all.x = TRUE)
signal_trajectory <- merge(signal_trajectory, bdev_grid[, .(bin, bin_midpoint)],
  by = "bin", all.x = TRUE)
signal_trajectory[is.na(n_cells), `:=`(n_cells = 0L, score_sum = 0)]
setorder(signal_trajectory, policy, knockout_target, genotype, bin)
signal_trajectory[, `:=`(
  rolling_n_cells = frollsum(n_cells, 5L, align = "center", fill = NA_real_),
  rolling_score_sum = frollsum(score_sum, 5L, align = "center",
    fill = NA_real_)), by = .(policy, knockout_target, genotype)]
signal_trajectory[, rolling_mean := fifelse(rolling_n_cells >= 20,
  rolling_score_sum / rolling_n_cells, NA_real_)]

projection <- fread(cmd = paste("zcat", shQuote(projection_path)))[,
  .(cell_id, projected_x, projected_y)]
umap <- merge(policy_query, projection, by = "cell_id", all.x = TRUE)
umap[, status := fifelse(accepted, as.character(genotype), "Rejected")]
umap[, draw_order := status != "Rejected"]
setorder(umap, draw_order)

write_tsv(sample_counts, file.path(stage_dir, "bdev_sample_counts.tsv"))
write_tsv(cutoff_summary, file.path(stage_dir, "cutoff_comparison.tsv"))
write_tsv(sample_performance, file.path(stage_dir,
  "cutoff_performance_by_bdev_sample.tsv"))
write_tsv(acceptance, file.path(stage_dir, "query_acceptance_comparison.tsv"))
write_tsv(region_retention, file.path(stage_dir,
  "original_region_retention_comparison.tsv"))
write_tsv(density, file.path(stage_dir, "query_density_comparison.tsv.gz"))
write_tsv(enrichment_regions[, !"run"], file.path(stage_dir,
  "wt_enrichment_regions_comparison.tsv"))
write_tsv(signal_trajectory, file.path(stage_dir,
  "signal_trajectory_comparison.tsv.gz"))

cols <- c("Rejected" = "grey75", "WT" = "#0072B2", "KO" = "#D55E00")
policy_cols <- c("Pooled-cell cutoff" = "#7F7F7F",
  "Equal-sample cutoff" = "#009E73",
  "Sqrt-on reliability cutoff" = "#CC79A7")
base_theme <- theme_bw(base_size = 10) + theme(panel.grid.minor = element_blank(),
  strip.text = element_text(face = "bold"), legend.position = "bottom")

# The score ordering is fixed, but each weighting defines a different ROC and
# operating point because held-out Bdev cells contribute differently.
roc_comparison <- rbindlist(lapply(seq_len(nrow(policy_info)), function(i) {
  p <- policy_info[i]
  ans <- make_roc(cv, cv[[p$weight_column]])
  ans[, policy := p$policy]
  ans
}))
roc_auc <- roc_comparison[order(false_positive_rate, sensitivity),
  .(weighted_auc = sum(diff(false_positive_rate) *
    (head(sensitivity, -1L) + tail(sensitivity, -1L)) / 2)), by = policy]
roc_points <- merge(policy_info[, .(policy, cutoff)], roc_comparison,
  by.x = c("policy", "cutoff"), by.y = c("policy", "threshold"),
  all.x = TRUE)
score_plot <- copy(cv)
score_plot[, truth_label := fifelse(trajectory_truth,
  "On trajectory", "Off trajectory")]
p_score <- ggplot(score_plot, aes(trajectory_support)) +
  geom_density(aes(fill = truth_label), alpha = .25, colour = NA) +
  geom_vline(data = policy_info,
    aes(xintercept = cutoff, colour = policy, linetype = policy),
    inherit.aes = FALSE, linewidth = .75) +
  facet_wrap(~held_out_sample, nrow = 1) +
  scale_colour_manual(values = policy_cols) +
  scale_linetype_manual(values = c("Pooled-cell cutoff" = "dashed",
    "Equal-sample cutoff" = "dotdash",
    "Sqrt-on reliability cutoff" = "solid")) +
  guides(linetype = "none") +
  scale_fill_manual(values = c("On trajectory" = "#56B4E9",
    "Off trajectory" = "grey65")) +
  labs(x = "Trajectory-support score", y = "Density",
    colour = "Selected cutoff", fill = "Known Bdev status",
    title = "A. Held-out Bdev scores and selected cutoffs") + base_theme
p_roc <- ggplot(roc_comparison,
    aes(false_positive_rate, sensitivity, colour = policy)) +
  geom_abline(slope = 1, intercept = 0, linetype = "dotted",
    colour = "grey60") +
  geom_path(linewidth = .9) +
  geom_point(data = roc_points, size = 2.6) + coord_equal() +
  scale_colour_manual(values = policy_cols) +
  labs(x = "Weighted false-positive rate", y = "Weighted sensitivity",
    colour = "Calibration weighting",
    title = "B. ROC under each calibration weighting",
    subtitle = paste(sprintf("%s AUC %.3f",
      sub(" cutoff$", "", roc_auc$policy), roc_auc$weighted_auc),
      collapse = "; ")) + base_theme
p_sample <- ggplot(sample_performance,
    aes(held_out_sample, balanced_accuracy, colour = policy, group = policy)) +
  geom_hline(yintercept = .5, linetype = "dotted", colour = "grey60") +
  geom_line(linewidth = .7) + geom_point(size = 2.4) +
  scale_colour_manual(values = policy_cols) +
  scale_y_continuous(limits = c(.5, 1), labels = scales::percent) +
  labs(x = "Held-out Bdev sample", y = "Balanced accuracy",
    colour = "Calibration weighting",
    title = "C. Performance within each original Bdev sample") + base_theme
cutoff_figure <- p_score / (p_roc | p_sample) +
  plot_annotation(title = "Comparison of pooled and sample-aware trajectory cutoffs",
    subtitle = "Similarity scores are unchanged; only calibration weights and the selected operating point differ") +
  plot_layout(heights = c(1.05, 1))
ggsave(file.path(stage_dir, "figures", "cutoff_comparison.pdf"),
  cutoff_figure, width = 13, height = 8.5, device = cairo_pdf)
ggsave(file.path(stage_dir, "figures", "cutoff_comparison.png"),
  cutoff_figure, width = 13, height = 8.5, dpi = 220, bg = "white")

p_umap <- ggplot(umap[is.finite(projected_x) & is.finite(projected_y)],
    aes(projected_x, projected_y, colour = status)) +
  geom_point(size = .18, alpha = .58) + facet_grid(sample_id ~ policy) +
  coord_equal() + scale_colour_manual(values = cols) +
  labs(x = "Bdev UMAP 1", y = "Bdev UMAP 2", colour = "Query status",
    title = "Query acceptance under pooled and sample-aware Bdev gates",
    subtitle = "PeakVI projection is unchanged; only the locked Bdev-derived cutoff differs") +
  base_theme
ggsave(file.path(stage_dir, "figures", "sample_weighted_gate_umap.pdf"),
  p_umap, width = 13, height = 13, device = cairo_pdf)
ggsave(file.path(stage_dir, "figures", "sample_weighted_gate_umap.png"),
  p_umap, width = 13, height = 13, dpi = 220, bg = "white")

p_density <- ggplot(density,
    aes(bin_midpoint, bdev_normalized_rolling_fraction, colour = genotype)) +
  geom_hline(yintercept = 1, linetype = "dotted") +
  geom_line(linewidth = .8, na.rm = TRUE) +
  facet_grid(target ~ policy, scales = "free_y") +
  scale_colour_manual(values = cols[c("WT", "KO")]) +
  labs(x = "Mapped Bdev pseudotime",
    y = "Retained query / Bdev rolling fraction", colour = "Genotype",
    title = "A. Enrichment after pooled and sample-aware gates",
    subtitle = "Current-mapped sample totals remain the fixed denominator") +
  base_theme
p_signal <- ggplot(signal_trajectory,
    aes(bin_midpoint, rolling_mean, colour = genotype)) +
  geom_line(linewidth = .8, na.rm = TRUE) +
  facet_grid(knockout_target ~ policy, scales = "free_y") +
  scale_colour_manual(values = cols[c("WT", "KO")]) +
  labs(x = "Mapped Bdev pseudotime",
    y = "5-bin mean respective signal score", colour = "Genotype",
    title = "B. Cytokine-response signal in retained cells") + base_theme
p_combined <- p_density / p_signal + plot_layout(heights = c(1, 1))
ggsave(file.path(stage_dir, "figures",
  "sample_weighted_enrichment_and_signal.pdf"), p_combined,
  width = 14, height = 10, device = cairo_pdf)
ggsave(file.path(stage_dir, "figures",
  "sample_weighted_enrichment_and_signal.png"), p_combined,
  width = 14, height = 10, dpi = 220, bg = "white")

fmt_pct <- function(x) sprintf("%.1f%%", 100 * x)
table_lines <- c(
  "| Approach | Cutoff | Weighted sensitivity | Weighted specificity | Sample BA range |",
  "|---|---:|---:|---:|---:|",
  vapply(seq_len(nrow(cutoff_summary)), function(i) {
    x <- cutoff_summary[i]
    sprintf("| %s | %.4f | %s | %s | %s–%s |", x$policy, x$cutoff,
      fmt_pct(x$calibration_weighted_sensitivity),
      fmt_pct(x$calibration_weighted_specificity),
      fmt_pct(x$minimum_sample_balanced_accuracy),
      fmt_pct(x$maximum_sample_balanced_accuracy))
  }, character(1)))
report <- c("# Sample-aware Bdev trajectory gate", "",
  "The frozen Bdev model, query projection, trajectory-support score, and preserved Bdev pseudotime are unchanged. Only the way held-out Bdev samples contribute to cutoff selection was changed.", "",
  "## Calibration summary", "", table_lines, "",
  "- **Pooled-cell:** every Bdev cell has equal influence; large samples dominate.",
  "- **Equal-sample:** every sample contributes equally within the on/off classes.",
  "- **Sqrt-on reliability (primary):** sample influence is proportional to the square root of its on-trajectory cell count, then balanced within the on/off classes. This moderates noisy small samples without restoring large-sample domination.", "",
  "All query density curves use the original currently mapped sample total as a fixed denominator, so filtering cannot create an apparent peak merely by renormalizing the retained subset.", "",
  "## Outputs", "",
  "- `cutoff_comparison.tsv`",
  "- `query_acceptance_comparison.tsv`",
  "- `original_region_retention_comparison.tsv`",
  "- `wt_enrichment_regions_comparison.tsv`",
  "- `figures/cutoff_comparison.pdf`",
  "- `figures/sample_weighted_gate_umap.pdf`",
  "- `figures/sample_weighted_enrichment_and_signal.pdf`", "",
  sprintf("Script version: `%s`.", script_version))
writeLines(report, file.path(stage_dir, "REPORT.md"))
write_json(list(status = "complete_unpromoted_report_only",
  script_version = script_version,
  primary_policy = "Sqrt-on reliability cutoff",
  parent_report = base_dir,
  completed_at = format(Sys.time(), "%Y-%m-%dT%H:%M:%S%z")),
  file.path(stage_dir, "receipt.json"), pretty = TRUE, auto_unbox = TRUE)

stopifnot(file.exists(file.path(stage_dir, "REPORT.md")),
  file.exists(file.path(stage_dir, "figures", "cutoff_comparison.pdf")),
  file.exists(file.path(stage_dir, "figures", "sample_weighted_gate_umap.pdf")))
if (!file.rename(stage_dir, output_dir))
  stop("Failed to finalize output directory", call. = FALSE)
cat("Completed sample-aware Bdev trajectory gate report: ", output_dir, "\n",
  sep = "")
